<?php
namespace App\Http\Controllers;
use App\Http\Requests\SaleReturnRequest;use App\Models\{Sale,SaleReturn,SaleReturnItem};use App\Services\SaleReturnService;use Illuminate\Http\Request;
class SaleReturnController extends Controller{public function index(Request $r){$company=$r->user()->company_id;return view('sale-returns.index',['returns'=>SaleReturn::with(['sale','customer'])->where('company_id',$company)->latest('return_date')->paginate(20),'sales'=>Sale::with('customer')->where('company_id',$company)->where('status','posted')->latest('sale_date')->limit(25)->get()]);}public function create(Request $r,$sale){$sale=Sale::with(['customer','items.product'])->where('company_id',$r->user()->company_id)->findOrFail($sale);$returned=SaleReturnItem::selectRaw('sale_item_id,SUM(quantity) quantity')->whereIn('sale_item_id',$sale->items->pluck('id'))->groupBy('sale_item_id')->pluck('quantity','sale_item_id');return view('sale-returns.create',compact('sale','returned'));}public function store(SaleReturnRequest $r,$sale,SaleReturnService $service){$sale=Sale::where('company_id',$r->user()->company_id)->findOrFail($sale);$return=$service->post($sale,$r->validated(),$r->user());return redirect()->route('sale-returns.show',$return)->with('success','Sales return posted successfully.');}public function show(Request $r,$sale_return){$return=SaleReturn::with(['sale','customer','items.product','creditNote'])->where('company_id',$r->user()->company_id)->findOrFail($sale_return);return view('sale-returns.show',compact('return'));}}
